package com.nbi.problem.service;

import com.nbi.problem.exception.*;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class TransferService {
    private final Map<String, BigDecimal> balances = new HashMap<>();

    public TransferService() {
        balances.put("SAV2001", new BigDecimal("1000000.00")); // Rajesh
        balances.put("CUR3001", new BigDecimal("250000.00"));  // Priya
    }

    public String transfer(String from, String to, BigDecimal amount) {
        if (!balances.containsKey(from) || !balances.containsKey(to))
            throw new AccountNotFoundException("Account not found: " + from + " or " + to);
        BigDecimal bal = balances.get(from);
        if (bal.compareTo(amount) < 0)
            throw new InsufficientFundsException(bal, amount);
        balances.put(from, bal.subtract(amount));
        balances.put(to, balances.get(to).add(amount));
        return "TXF-" + UUID.randomUUID().toString().substring(0, 8);
    }
}
```

