// ─── File: src/main/java/com/nbi/problem/controller/TransferController.java ───
package com.nbi.problem.controller;

import com.nbi.problem.service.TransferService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.net.URI;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/transfers")
public class TransferController {

    private final TransferService service;
    public TransferController(TransferService service) { this.service = service; }

    @PostMapping
    public ResponseEntity<String> create(@RequestBody Map<String, String> body) {
        String txId = service.transfer(body.get("from"), body.get("to"),
                new BigDecimal(body.get("amount")));
        return ResponseEntity.created(URI.create("/api/v1/transfers/" + txId)).body(txId);
    }
}
```
